            "❌ **기각 1 — 씨어스 유형 차단 브레이크 9개 전부 무효.** 씨어스는 120일 **-54.5%** · 60일 -38.3% · 20일 -23.4% · POC 대비 **-25%**인 종목이었다. 그런 종목을 막는 브레이크를 실측했다(알파분위≥85 모집단 1,015행 · 21일, 일별 paired t): `ret120≤-40` t=-0.59 · `ret60≤-30` t=+0.34 · `ret20≤-20` t=-0.97 · `POC 아래` t=+0.28 · `POC_GAP≤-20` t=+0.28 · `ret120&POC` t=-0.81 · `ret5≤-10` t=-0.65 · `ret120&ret60` t=+0.26 · `LT_PCTL<40` **t=+2.00(양수 — 차단하면 손해)**. **전부 유의하지 않았다**(|t|<2.0, p>0.10)고 여러 후보는 이상치 제거 시 부호가 뒤집혔다. 근거 없는 필터는 넣지 않는다(v51에서 걷어낸 실수의 반복).",
            "❌ **기각 2 — 가드 경고 노출·사이징 복원 모두 해롭다.** 씨어스 8/11 행에는 `GUARD_TRENDLINE_BROKEN=4` · `GUARD_REASON=\"G2RR×0.5 · G5추세붕괴4축\"` · **`GUARD_FORCE_EXIT_ALERT=True`** · `GUARD_KELLY_MULT=0.0`이 붙어 있었고, 이것들은 **UI 어디에서도 참조되지 않는다**(계산만 되고 아무에게도 안 보인다). 그래서 노출을 검토했으나 재검증 결과 **역예측**이었다 — 유니버스 6,697행·21일에서 `GUARD_KELLY_MULT=0` 종목이 **+1.90%p 더 좋았고**(t=2.11, p=0.048), 강제청산경고 종목도 +1.51%p(t=1.91). 알파분위≥85 안에서는 |t|≤0.25로 신호가 없다. **v45가 사이징에서 가드 배수를 분리한 판단이 더 큰 표본에서 재현됐다** — 경고로 띄우면 오히려 좋은 종목을 피하게 만든다. 노출도, 사이징 복원도 하지 않는다.",
            "✅ **알파 게이트 자체는 정상이었다.** 생존편향을 제거한 실측(120개 캐시 합집합, 1,729종목, 커버리지 98.6%)에서 게이트 통과군(알파분위≥85 & LT>30)의 5일 실현수익은 **+4.03%**(승률 77.5% · 손절률 3.9%), 유니버스는 -1.08%였다. **씨어스는 엔진이 망가져서 나온 픽이 아니라 양의 기대값 안에서 난 손실이다.** 그래서 신호를 바꾸지 않았다.",
            "🧪 **신규 테스트(`tests/test_v61_position_risk.py`):** 실제 손절 손실을 가격에서 계산하는지 · 수량 없으면 금액을 만들지 않는지 · 캡을 손실이라 부르지 않는지 · 캡 미구속을 화면에 표시하는지 · 옛 오표기 툴팁이 되살아나면 실패 · `POSITION_PCT` 툴팁 정정 유지 · 88% 캡 초과 전제 고정 · 씨어스 행 재현 · **기각한 후보가 몰래 되살아나면 실패**(미검증 장기하락 브레이크 소스 검사, 가드 배수 사이징 미적용 유지, 가드 경고 UI 미배선).",
