            "🔇 **조용히 채우지 않는다:** 복구 건수·미복구 건수·결측 비율·미복구 종목 예시를 리포트로 남기고 배치 로그에 한 줄 찍는다. 결측 비율 5% 이상이거나 미복구가 남으면 **경고로 승격**하고 \"업종 결측은 그 행이 섹터/뉴스/전략 단계 뒤에 합류했다는 신호다 — LDY_SCORE·NEWS_SCORE 등도 비어 있다\"를 함께 남긴다. 조용히 채우면 **근본 원인이 또 숨는다**(v55.4~v58에서 반복해 잡은 유형).",
