            "🧪 **신규 테스트 23개(`tests/test_v59_sector_gap.py`):** ① 표시 — 결측 부모 크래시 재현 케이스가 통과하는지, 6가지 공백 형태, 값/색 결측, 전체 0, 실제 배치 CSV ② 돈 — 결측이 가짜 섹터 평균을 받지 않고 중립 배수인지, `astype(str).fillna(\"?\")` 패턴이 되살아나면 실패(주석의 기록은 허용하되 코드 라인만 검사) ③ 복구 — 같은 분류기 사용, 실제 30건 전량 복구, 분류기 부재 시 침묵 대신 경고, 완전 복구돼도 결측 사실은 보고, 깨끗하면 조용히, 다른 결측 컬럼은 안 만듦 ④ 배선 — 복구가 켈리보다 먼저인지 ⑤ 격리 — 서드파티를 sys.modules에서 지우는 테스트가 다시 생기면 실패(+ 그 탐지기 자체의 mutation 테스트).",
