            "🧨 **진짜 원인 — 픽스처가 서드파티를 `sys.modules`에서 raw del 했다:** 5개 파일(`test_regime`·`test_robustness`·`test_preset_comparison`·`test_train_test_split`·`test_verdict_anomaly`)이 격리를 위해 `del sys.modules[mod]`로 `plotly*`를 통째로 지웠다. 지워도 이미 import해 둔 모듈(`chart_components`)은 **옛 클래스 객체를 계속 들고 있고**, 이후 누가 plotly를 다시 import하면 `Template`·`Figure` 클래스가 **새로 만들어진다** → 옛 검증기가 새 인스턴스를 모르는 타입으로 거부. 실측으로 재로딩 시 `Template` 객체 동일성이 실제로 깨지는 것을 확인했다. **부수 피해가 하나 더:** raw del 뒤에 `monkeypatch.setitem(sys.modules, \"plotly\", 가짜)`를 하면 monkeypatch가 \"원래 없었음\"으로 기록해 teardown에서 **원복이 아니라 삭제**를 한다 — 진짜 plotly가 세션에서 영구히 사라진다. `test_portfolio_swap`이 같은 방식으로 nicegui를 지웠고, 그 뒤 `test_pick_top1_eligible_hotfix`가 \"없으니 만들자\"며 **가짜 nicegui를 세션 끝까지 영구 설치**했다.",
            "🛡️ **하드 게이트로 고정(`tests/conftest.py` 신설):** 세션 시작 시 `plotly`·`nicegui` 모듈 집합을 스냅샷(지연 로딩까지 강제)하고, 매 테스트 teardown **후**(픽스처 원복이 끝난 뒤, `trylast`) 어긋난 항목을 원복한 다음 **그 테스트를 실패시킨다**. 조용히 고쳐주면 누출이 계속 새로 생긴다. 5개 픽스처는 plotly/nicegui 삭제를 제거했고(`monkeypatch.setitem` 가짜만으로 격리 목적은 그대로 달성 — 138개 테스트 전부 통과 확인), `test_pick_top1`의 영구 대입은 `monkeypatch.setitem`으로 바꿨다. 추가로 **소스 수준 회귀 가드**(AST로 `del sys.modules`를 지배하는 if 조건만 검사 — 줄 단위 검색은 정상 스텁 정리 2건을 오탐했다)와 **가드 자체의 mutation 테스트**를 넣었다. 실제로 오염 패턴을 되살려 두 게이트가 모두 잡는 것을 확인했다(v56의 죽은 게이트 감사와 같은 방식).",
