            "🏗️ **구조적 결함 — 판정과 설명이 분리돼 있었다:** `apply_alpha_entry_gate`는 4조건 AND(리스크가드 · 알파문턱 · ~하드블록 · 저점추세)를 **boolean 하나로만** 내보냈다. 그래서 하류 `recommendation_quality._reasons`가 사유를 **재추론**해야 했고, 알파·LT 어느 것도 안 걸리면 '진입 조건 미달'로 뭉갰다. 그 문구를 `decision_center._humanize_reason`이 '**AI 알파 진입 기준 미달**'로 번역하면서 알파 100점 종목에 알파 탓이 붙었다. → **판정하는 모듈이 사유를 남긴다**(`ALPHA_ENTRY_BLOCK_REASON` 신규). 실패한 조건을 결정적인 순서로 **전부** 적는다(예: 비에이치 = `시장 전체 신규진입 차단 · 저점추세 당일 하위 12%`). 구 CSV엔 컬럼이 없으므로 하드블록 폴백을 별도로 남겼다.",
            "🏷️ **섹션 라벨 거짓도 수정:** 제목이 '가장 가까운 관찰 후보 / **조건에 가까운 순서**'였지만 실제 정렬키는 `ALPHA_SCORE` 내림차순이다. 게다가 전 종목 차단일에는 '가까운' 것 자체가 없다(1위가 알파 100점으로 문턱을 통과했는데도 픽이 아니다). → '**AI 알파 상위 관찰 후보 / AI 알파 점수 순**'으로 바꾸고, 차단 중에는 '오늘은 전 종목 신규진입이 보류돼 조건 근접도와 무관하다'를 덧붙인다.",
            "🧪 **신규 테스트 15개(`test_v56_gate_reason_truth.py`):** 조건별 사유 문구, 복수 실패 시 우선순위, 구 CSV 폴백, 화면 번역이 거짓을 만들지 않는지, 그리고 **실제 8/6 배치 회귀**(알파 100.0/98.2 종목의 사유에 '알파'가 등장하면 실패).",
