            "⚠️ **v44 낙폭추격 경고 노출:** 이격 -15% 이하 구간의 실측 손실(10일 -3.6% · 승률 41%)을 액션레일에 표시한다.",
            "🎯 **목록 사유가 게이트 실제 임계와 어긋나 있었다:** RR 임계를 **1.2**로 표시했는데 게이트 실제값은 **1.0**(`scoring_engine._risk_gate`) — 통과한 종목에 '부족'이라는 **거짓 사유**가 붙었다. POC 임계는 **30**인데 게이트는 **20**(v27 검증: 20% 초과 구간 승률 20%/12%) — 실제로 차단되는 21~30% 구간을 '양호'로 표시했다. 둘 다 게이트 실제값으로 맞췄다.",
